//! `Mth.atan2`: vanilla's table-driven arctangent, with its Java 25
//! `Math.asin`/`Math.cos` tables; and `Mth.sin`/`Mth.cos`, the 65536-entry
//! float sine table (`(float)Math.sin(i / 10430.378350470453)`) indexed by
//! `(long)(x * 10430.378350470453) & 65535`.

const SIN_SCALE: f64 = 10430.378350470453;

fn sin_table() -> &'static [f32] {
    static TABLE: std::sync::OnceLock<Vec<f32>> = std::sync::OnceLock::new();
    TABLE.get_or_init(|| (0..65536).map(|i| crate::jmath::sin(f64::from(i) / SIN_SCALE) as f32).collect())
}

/// `Mth.sin`.
pub fn sin(x: f64) -> f32 {
    sin_table()[((x * SIN_SCALE) as i64 & 65535) as usize]
}

/// `Mth.cos`: a quarter turn on in the same table.
pub fn cos(x: f64) -> f32 {
    sin_table()[((x * SIN_SCALE + 16384.0) as i64 & 65535) as usize]
}

/// `Mth.RAD_TO_DEG` widened to double: the decompiled source prints this
/// folded constant as `180.0F / (float)Math.PI`, but the bytecode multiplies
/// once by it.
pub const RAD_TO_DEG: f64 = 57.2957763671875;

/// `Mth.atan2`: a biased 257-entry asin table and a fast reciprocal root.
pub fn atan2(mut y: f64, mut x: f64) -> f64 {
    let d2 = x * x + y * y;
    if d2.is_nan() {
        return f64::NAN;
    }
    let neg_y = y < 0.0;
    if neg_y {
        y = -y;
    }
    let neg_x = x < 0.0;
    if neg_x {
        x = -x;
    }
    let steep = y > x;
    if steep {
        std::mem::swap(&mut x, &mut y);
    }
    let half = 0.5 * d2;
    let bits = 6910469410427058090_u64.wrapping_sub(d2.to_bits() >> 1);
    let root = f64::from_bits(bits);
    let inv = root * (1.5 - half * root * root);
    x *= inv;
    y *= inv;
    let bias = f64::from_bits(4805340802404319232);
    let yp = bias + y;
    let index = yp.to_bits() as u32 as usize;
    let phi = ASIN[index];
    let cphi = COS[index];
    let sphi = yp - bias;
    let sd = y * cphi - x * sphi;
    let d = (6.0 + sd * sd) * sd * 0.16666666666666666;
    let mut theta = phi + d;
    if steep {
        theta = std::f64::consts::FRAC_PI_2 - theta;
    }
    if neg_x {
        theta = std::f64::consts::PI - theta;
    }
    if neg_y {
        theta = -theta;
    }
    theta
}

